import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class FeatureOrchestrator {
    private final ExecutorService asyncPool = Executors.newFixedThreadPool(10);

    public OrderResponse processOrder(OrderRequest request) {
        // 1. Synchronous core validation and persistence
        validateInventory(request);
        Order savedOrder = saveToDatabase(request);

        // 2. Asynchronous side-effects (Notifications, Analytics)
        CompletableFuture.runAsync(() -> sendConfirmationEmail(savedOrder), asyncPool)
            .exceptionally(ex -> {
                log.error("Failed to send async confirmation email", ex);
                return null;
            });

        // 3. Return immediate synchronous response
        return new OrderResponse(savedOrder.getId(), "SUCCESS");
    }

